package com.enterpriseflow.controller; import com.enterpriseflow.api.ApiResponse; import com.enterpriseflow.service.NotificationService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/notifications")public class NotificationController{private final NotificationService s;public NotificationController(NotificationService x){s=x;}@GetMapping public ApiResponse<List<Map<String,Object>>>list(Authentication a){return ApiResponse.success("Notifications retrieved.",s.list(a.getName()));}@PostMapping("/{id}/read")public ApiResponse<Void>read(Authentication a,@PathVariable UUID id){s.read(a.getName(),id);return ApiResponse.success("Notification marked as read.",null);}@PostMapping("/read-all")public ApiResponse<Void>readAll(Authentication a){s.markAllRead(a.getName());return ApiResponse.success("All notifications marked as read.",null);}}
